  if (observed.status !== 'PRESENT' || typeof observed.birthToken !== 'string') {
    return { ok: true, status: 'INDETERMINATE' };
  }
  return observed.birthToken === pidIdentity.birth_observed_at
    ? { ok: true, status: 'LIVE' }
    : { ok: true, status: 'ABSENT' };
