      approvalPolicy: 'never',
      approvalsReviewer: 'user',
      baseInstructions: opts.baseInstructions,
      config: null,
      cwd: opts.cwd,
      developerInstructions: opts.developerInstructions,
      ephemeral: false,
      model: null,
      modelProvider: null,
      personality: null,
      sandbox: null,
      serviceTier: null,
