// shape must be exactly this closed 6-field set -- no extra/missing keys.
const CREDENTIAL_EVIDENCE_RECORD_KEYS_SORTED = Object.freeze(['checkpoints', 'complete', 'mode', 'root_ids', 'run_id', 'schema']);

